import "sort"

func TopTwo(xs []int) []int {
	if len(xs) < 2 {
		panic("input slice must have at least two elements")
	}
	sorted := make([]int, len(xs))
	copy(sorted, xs)
	sort.Sort(sort.Reverse(sort.IntSlice(sorted)))
	return sorted[:2]
}

